BEGIN;
CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sources(id text PRIMARY KEY,source_type text NOT NULL,source_title text NOT NULL,source_url text NOT NULL CHECK(source_url LIKE 'https://%'),publisher text NOT NULL,source_published_at timestamptz,license text NOT NULL,attribution text NOT NULL,redistribution_allowed boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS content_items(canonical_id text PRIMARY KEY,category text NOT NULL CHECK(category IN ('home','anatomy','diseases','medicines')),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','needs_review','approved','published','withdrawn')),review_status text NOT NULL DEFAULT 'needs_review' CHECK(review_status IN ('draft','needs_review','approved','published','withdrawn')),clinical boolean NOT NULL DEFAULT false,reviewer_id text,medically_reviewed_at timestamptz,source_id text NOT NULL REFERENCES sources(id),applicable_region text NOT NULL DEFAULT 'global',revision integer NOT NULL DEFAULT 1 CHECK(revision>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(NOT clinical OR status<>'published' OR (reviewer_id IS NOT NULL AND medically_reviewed_at IS NOT NULL AND review_status IN ('approved','published'))));
CREATE TABLE IF NOT EXISTS content_translations(content_id text NOT NULL REFERENCES content_items(canonical_id),locale text NOT NULL CHECK(locale IN ('ar','en')),title text NOT NULL,body text NOT NULL,revision integer NOT NULL DEFAULT 1,PRIMARY KEY(content_id,locale));
CREATE TABLE IF NOT EXISTS content_revisions(content_id text NOT NULL REFERENCES content_items(canonical_id),revision integer NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(content_id,revision));
CREATE TABLE IF NOT EXISTS body_systems(id text PRIMARY KEY,content_id text UNIQUE REFERENCES content_items(canonical_id));
CREATE TABLE IF NOT EXISTS organs(id text PRIMARY KEY,body_system_id text REFERENCES body_systems(id),content_id text REFERENCES content_items(canonical_id));
CREATE TABLE IF NOT EXISTS anatomy_structures(id text PRIMARY KEY,organ_id text REFERENCES organs(id),content_id text REFERENCES content_items(canonical_id));
CREATE TABLE IF NOT EXISTS diseases(id text PRIMARY KEY,content_id text REFERENCES content_items(canonical_id));
CREATE TABLE IF NOT EXISTS active_ingredients(id text PRIMARY KEY,generic_name text NOT NULL,content_id text REFERENCES content_items(canonical_id));
CREATE TABLE IF NOT EXISTS medicine_products(id text PRIMARY KEY,ingredient_id text REFERENCES active_ingredients(id),brand_name text NOT NULL,region text NOT NULL);
CREATE TABLE IF NOT EXISTS citations(content_id text REFERENCES content_items(canonical_id),source_id text REFERENCES sources(id),locator text NOT NULL DEFAULT '',PRIMARY KEY(content_id,source_id,locator));
CREATE TABLE IF NOT EXISTS media_assets(id text PRIMARY KEY,content_id text REFERENCES content_items(canonical_id),source_id text NOT NULL REFERENCES sources(id),bucket text NOT NULL,object_key text NOT NULL,mime_type text NOT NULL,bytes bigint NOT NULL CHECK(bytes>0),sha256 text NOT NULL CHECK(sha256 ~ '^[0-9a-f]{64}$'),locale text,quality text,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','withdrawn')),UNIQUE(bucket,object_key));
CREATE TABLE IF NOT EXISTS content_packs(id text NOT NULL,version integer NOT NULL CHECK(version>0),schema_version integer NOT NULL DEFAULT 1,scope_type text NOT NULL,scope_id text NOT NULL,manifest jsonb NOT NULL,source_id text NOT NULL REFERENCES sources(id),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','withdrawn')),published_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id,version));
CREATE TABLE IF NOT EXISTS content_pack_files(pack_id text NOT NULL,version integer NOT NULL,relative_path text NOT NULL CHECK(relative_path !~ '(^/|(^|/)\.\.(/|$)|\\)'),asset_id text NOT NULL REFERENCES media_assets(id),PRIMARY KEY(pack_id,version,relative_path),FOREIGN KEY(pack_id,version) REFERENCES content_packs(id,version));
CREATE TABLE IF NOT EXISTS content_pack_dependencies(pack_id text NOT NULL,version integer NOT NULL,dependency_id text NOT NULL,dependency_version integer NOT NULL,PRIMARY KEY(pack_id,version,dependency_id),FOREIGN KEY(pack_id,version) REFERENCES content_packs(id,version),FOREIGN KEY(dependency_id,dependency_version) REFERENCES content_packs(id,version),CHECK(pack_id<>dependency_id));
CREATE TABLE IF NOT EXISTS content_pack_items(pack_id text NOT NULL,version integer NOT NULL,content_id text NOT NULL REFERENCES content_items(canonical_id),PRIMARY KEY(pack_id,version,content_id),FOREIGN KEY(pack_id,version) REFERENCES content_packs(id,version));
CREATE TABLE IF NOT EXISTS editorial_reviews(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,content_id text NOT NULL REFERENCES content_items(canonical_id),reviewer_id text NOT NULL,decision text NOT NULL CHECK(decision IN ('needs_review','approved','withdrawn')),notes text NOT NULL,reviewed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id text NOT NULL,action text NOT NULL,target_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS content_category_status ON content_items(category,status,canonical_id);
CREATE INDEX IF NOT EXISTS content_updated ON content_items(updated_at,canonical_id);
CREATE INDEX IF NOT EXISTS content_source ON content_items(source_id);
CREATE INDEX IF NOT EXISTS translation_search ON content_translations USING gin(to_tsvector('simple',title || ' ' || body));
CREATE INDEX IF NOT EXISTS pack_scope ON content_packs(scope_type,scope_id,status);
CREATE INDEX IF NOT EXISTS media_content ON media_assets(content_id);
CREATE OR REPLACE VIEW public_content AS SELECT c.canonical_id,c.category,c.revision,c.updated_at,c.review_status,c.clinical,s.source_title,s.source_url,s.publisher,s.source_published_at,s.license,s.attribution,c.medically_reviewed_at,c.applicable_region,t.locale,t.title,t.body FROM content_items c JOIN sources s ON s.id=c.source_id JOIN content_translations t ON t.content_id=c.canonical_id WHERE c.status='published' AND s.redistribution_allowed AND (NOT c.clinical OR (c.review_status IN ('approved','published') AND c.reviewer_id IS NOT NULL AND c.medically_reviewed_at IS NOT NULL));
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
COMMIT;
